package ca.yorku.eecs3311.coursepilot.application.service;
import ca.yorku.eecs3311.coursepilot.application.dto.*; import ca.yorku.eecs3311.coursepilot.domain.model.*; import ca.yorku.eecs3311.coursepilot.domain.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.*; import java.util.*;
@Service public class StudyPlanService {private final CourseService courses;private final ProgressService progress;private final StudyPlanRepository plans;private final Map<String,StudyPlanningStrategy> strategies=Map.of("BALANCED",new BalancedStudyStrategy(),"WEAK_TOPIC_FOCUSED",new WeakTopicFocusedStrategy(),"EXAM_CRAM",new ExamCramStrategy());public StudyPlanService(CourseService c,ProgressService p,StudyPlanRepository r){courses=c;progress=p;plans=r;}
 @Transactional public StudyPlanResponse create(Long courseId,LocalDate start,LocalDate target,Integer minutes,String strategy){if(start==null||target==null||target.isBefore(start))throw new IllegalArgumentException("Target date must be on or after the start date.");if(minutes==null||minutes<1)throw new IllegalArgumentException("Available study time must be positive.");StudyPlanningStrategy selected=strategies.get(Optional.ofNullable(strategy).orElse("BALANCED").toUpperCase(Locale.ROOT));if(selected==null)throw new IllegalArgumentException("Unsupported study strategy.");var plan=new StudyPlan(courses.getCourseEntity(courseId),start,target,minutes,selected.name());var activity=selected.build(start,target,minutes,progress.summarize(courseId).topics());int total=activity.stream().mapToInt(StudyPlanningStrategy.Activity::minutes).sum();if(total>minutes)throw new IllegalArgumentException("Generated schedule exceeds available study time.");int i=1;for(var a:activity)plan.addItem(new StudyPlanItem(plan,a.date(),i++,a.activity(),a.minutes()));return StudyPlanResponse.from(plans.save(plan));}
 @Transactional public StudyPlanResponse updateItem(Long courseId,Long planId,Long itemId,LocalDate date,String activity,Integer minutes,boolean completed,Integer actualMinutes){if(date==null)throw new IllegalArgumentException("A session date is required.");if(activity==null||activity.isBlank())throw new IllegalArgumentException("A session activity is required.");if(activity.length()>500)throw new IllegalArgumentException("The session activity is too long.");if(minutes==null||minutes<1)throw new IllegalArgumentException("Planned minutes must be positive.");if(actualMinutes==null||actualMinutes<0)throw new IllegalArgumentException("Actual minutes cannot be negative.");var plan=plans.findOwned(planId,courseId).orElseThrow(()->new IllegalArgumentException("Study plan was not found for this course."));var item=plan.getItems().stream().filter(candidate->candidate.getId().equals(itemId)).findFirst().orElseThrow(()->new IllegalArgumentException("Study session was not found for this plan."));item.update(date,activity,minutes,completed,actualMinutes);return StudyPlanResponse.from(plans.save(plan));}
 public List<StudyPlanResponse> list(Long courseId){return plans.findByCourseId(courseId).stream().map(StudyPlanResponse::from).toList();}public StudyPlanResponse get(Long courseId,Long id){return StudyPlanResponse.from(plans.findOwned(id,courseId).orElseThrow(()->new IllegalArgumentException("Study plan was not found for this course.")));}}
